import { afterEach, describe, expect, it, vi } from "vitest";
import type { AudioTrack, VideoTrack } from "../../src/types";
import { stubBrowserGlobals } from "../helpers/browser-globals";
import {
  audioPacket,
  makePipelinePlayer,
  packetRun,
  videoPacket,
} from "../helpers/pipeline-player";

// dist/wasm/movi.js is generated by build:wasm (Docker/4090) and is absent in
// the unit-test CI job (dist/ is gitignored). MoviPlayer's module graph imports
// it eagerly via FFmpegLoader; these tests never load/run the WASM, so stub the
// module so importing the player graph resolves without the built artifact.
vi.mock("../../dist/wasm/movi.js", () => ({ default: vi.fn(async () => ({})) }));

vi.mock("dashjs", () => ({
  MediaPlayer: vi.fn(),
}));

vi.mock("shaka-player/dist/shaka-player.compiled", () => ({
  default: {
    Player: {
      isBrowserSupported: vi.fn(() => false),
    },
    polyfill: {
      installAll: vi.fn(),
    },
    net: {
      NetworkingEngine: {
        RequestType: {
          LICENSE: 1,
        },
      },
    },
  },
}));

const videoTrack: VideoTrack = {
  id: 1,
  type: "video",
  codec: "h264",
  width: 1920,
  height: 1080,
  frameRate: 24,
};

const trueHdTrack: AudioTrack = {
  id: 2,
  type: "audio",
  codec: "truehd",
  codecId: 86060,
  channels: 8,
  sampleRate: 48000,
};

afterEach(() => {
  vi.unstubAllGlobals();
});

describe("MoviPlayer seek sync", () => {
  it("does not complete a video seek when the forced timeout fires before the first frame", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    const seeked = vi.fn();

    player.trackManager.setTracks([videoTrack]);
    player.on("seeked", seeked);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");
    stateManager.setState("seeking");

    Object.assign(player as any, {
      seekSessionId: 1,
      seekArmedSessionId: 1,
      seekTargetTime: 42,
      waitingForVideoSync: true,
      wasPlayingBeforeSeek: true,
      videoRenderer: {
        getQueueSize: () => 0,
      },
    });

    (player as any).notifySeekCompletion(42, true);

    expect(seeked).not.toHaveBeenCalled();
    expect((player as any).waitingForVideoSync).toBe(true);
    expect((player as any).seekTargetTime).toBe(42);
    expect(stateManager.getState()).toBe("buffering");
    expect((player as any).wasPlayingBeforeRebuffer).toBe(true);
  }, 20_000);

  // Merge regression guard (upstream 0.3.5): the forced-timeout path above leaves
  // us buffering + sync-armed on purpose. Upstream's canResume rewrite dropped
  // our `!waitingForVideoSync` guard (safe upstream because upstream completes
  // the seek before buffering; unsafe with our stay-armed design). Without the
  // guard, the process loop resumes over a black screen mid-seek, then snaps
  // back to paused when the frame lands. Everything else the resume gate asks
  // for is satisfied here — a second of media queued ahead on both streams, a
  // decoded frame to show, audio buffered — so the ONLY thing that may keep us
  // buffering is the guard; this locks it in.
  it("does not resume while a forced-timeout seek is still sync-armed (no premature black-screen resume)", async () => {
    const f = await makePipelinePlayer({
      state: "buffering",
      waitingForVideoSync: true,
      rendererQueue: 5,
      audioBuffered: 5.1,
      queuedVideo: packetRun((t) => videoPacket(t), 42, 45, 1 / 24),
      queuedAudio: packetRun((t) => audioPacket(t), 42, 45, 0.02),
    });
    // Demuxed 10s past target (>SEEK_MAX_DEMUX_AHEAD_SECONDS=8): trips
    // seekReadAheadExceeded() so processLoop returns right after the resume
    // gate, before the demux/EOF path — isolating the gate under test.
    f.player.seekTargetTime = 42;
    f.player.seekDemuxAheadTime = 52;
    f.player.seekSyncArmedAt = performance.now() - 1000; // far from the 12s hard-timeout

    await f.tick();

    // Seek still armed → must stay buffering, must NOT resume over a black screen.
    expect(f.player.stateManager.getState()).toBe("buffering");
    expect(f.player.waitingForVideoSync).toBe(true);
    expect(f.player.wasPlayingBeforeRebuffer).toBe(true);
    expect(f.player.audioRenderer.resumeFromBuffering).not.toHaveBeenCalled();
  }, 20_000);

  // The old hold was a separate stash with its own packet cap (512) and a
  // window past the target (4s), dropping whatever fell outside. The held
  // audio now waits in its stream's queue like any other packet, unfed, and
  // what bounds it is the queues' shared byte ceiling: reading stops there
  // even though the video side is still asking for more.
  it("holds audio in its queue while a video seek waits for the first frame, up to the byte ceiling", async () => {
    const big = 100 * 1024;
    const f = await makePipelinePlayer({
      waitingForVideoSync: true,
      rendererQueue: 0,
      reads: packetRun((t) => audioPacket(t, big), 10, 10 + 700 * 0.002, 0.002),
    });
    f.player.seekTargetTime = 10;
    await f.tick();
    expect(f.audioDecode).not.toHaveBeenCalled();
    const ceiling = (f.player.constructor as any).MAX_QUEUE_BYTES as number;
    expect(f.player.audioQueue.bytes).toBeGreaterThanOrEqual(ceiling);
    expect(f.player.audioQueue.bytes).toBeLessThan(ceiling + big);
    expect(f.readPacket.mock.calls.length).toBeLessThan(700);
  }, 20_000);

  it("read-ahead cap engages only after demuxing past the target while waiting for video sync", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    const MAX_AHEAD = (MoviPlayer as any).SEEK_MAX_DEMUX_AHEAD_SECONDS as number;

    // Not waiting for sync → never caps normal playback.
    Object.assign(player as any, {
      waitingForVideoSync: false,
      seekTargetTime: 100,
      seekDemuxAheadTime: 100 + MAX_AHEAD + 50,
    });
    expect((player as any).seekReadAheadExceeded()).toBe(false);

    // Waiting, but demuxed only a little past target → keep reading.
    Object.assign(player as any, {
      waitingForVideoSync: true,
      seekTargetTime: 100,
      seekDemuxAheadTime: 100 + MAX_AHEAD - 1,
    });
    expect((player as any).seekReadAheadExceeded()).toBe(false);

    // Waiting and demuxed well past target → stop reading (traffic cap).
    (player as any).seekDemuxAheadTime = 100 + MAX_AHEAD + 1;
    expect((player as any).seekReadAheadExceeded()).toBe(true);
  }, 20_000);

  it("hard watchdog trips only after the timeout while a frame-starved seek is armed", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    const LIMIT = (MoviPlayer as any).SEEK_SYNC_HARD_TIMEOUT_MS as number;

    // Not waiting → never trips.
    Object.assign(player as any, {
      waitingForVideoSync: false,
      seekSyncArmedAt: 1000,
    });
    expect((player as any).seekSyncHardTimedOut(1000 + LIMIT + 1)).toBe(false);

    // Waiting, armed, but still within the limit → hold.
    Object.assign(player as any, {
      waitingForVideoSync: true,
      seekSyncArmedAt: 1000,
    });
    expect((player as any).seekSyncHardTimedOut(1000 + LIMIT - 1)).toBe(false);

    // Waiting past the limit → trip (terminal completion).
    expect((player as any).seekSyncHardTimedOut(1000 + LIMIT + 1)).toBe(true);

    // Disarmed (armedAt 0) → never trips even if long elapsed.
    (player as any).seekSyncArmedAt = 0;
    expect((player as any).seekSyncHardTimedOut(1_000_000)).toBe(false);
  }, 20_000);

  it("clears the read-ahead cap and watchdog arming when a seek really completes", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    const seeked = vi.fn();
    player.trackManager.setTracks([videoTrack]);
    player.on("seeked", seeked);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");
    stateManager.setState("seeking");

    Object.assign(player as any, {
      seekSessionId: 1,
      seekArmedSessionId: 1,
      seekTargetTime: 42,
      waitingForVideoSync: true,
      seekSyncArmedAt: 5,
      seekDemuxAheadTime: 55,
      // Paused-completion path: no resume machinery, but the seek still fully
      // completes and the read-ahead/watchdog arming must be cleared.
      wasPlayingBeforeSeek: false,
      wasPlayingBeforeRebuffer: false,
      videoRenderer: {
        getQueueSize: () => 1,
      },
    });

    // forced=false, first frame present → real completion (paused) path.
    (player as any).notifySeekCompletion(42);

    expect((player as any).waitingForVideoSync).toBe(false);
    expect((player as any).seekSyncArmedAt).toBe(0);
    expect((player as any).seekDemuxAheadTime).toBe(-1);
    expect((player as any).seekReadAheadExceeded()).toBe(false);
    expect((player as any).seekSyncHardTimedOut(10_000_000)).toBe(false);
  }, 20_000);

  it("does not start pause-time prebuffer while a seek is still waiting for video sync", async () => {
    const setIntervalSpy = vi.fn(() => 123);
    vi.stubGlobal("document", {
      hidden: false,
      visibilityState: "visible",
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
    });
    vi.stubGlobal("window", {
      addEventListener: vi.fn(),
      removeEventListener: vi.fn(),
      setInterval: setIntervalSpy,
      clearInterval: vi.fn(),
    });
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});

    Object.assign(player as any, {
      demuxer: {},
      eofReached: false,
      waitingForVideoSync: true,
      seekTargetTime: 42,
    });

    (player as any).startPauseBuffering();

    expect(setIntervalSpy).not.toHaveBeenCalled();
    expect((player as any).pauseBufferTimerId).toBeNull();
  }, 20_000);

  // During a rebuffer the renderer is suspended and the clock paused, so the
  // audio cushion is frozen at whatever it held when the stall hit. When that
  // cushion gated every read, a player that stalled above its target never
  // read, never got a frame, and never resumed — measured on a real HEVC
  // Main10 + FLAC source over OpenList: 8.6s buffered against the 5.0s
  // target, `media clock rate 0.340`, stuck in "buffering" for the rest of
  // the run. Software audio full and queued, video empty: read.
  it("keeps demuxing during rebuffer when software audio is full but video has no frame", async () => {
    const f = await makePipelinePlayer({
      state: "buffering",
      audioBuffered: 5.1,
      rendererQueue: 0,
      queuedAudio: packetRun((t) => audioPacket(t), 10, 16, 0.02),
    });
    await f.tick();
    expect(f.readPacket).toHaveBeenCalled();
  }, 20_000);

  // …and what bounds that read is the readahead, not the audio cushion: once
  // the video decoder has packets to work with and both queues hold their
  // readahead, reading more would only race ahead of the decoder.
  it("bounds rebuffer demuxing once the video side already has its readahead queued", async () => {
    const f = await makePipelinePlayer({
      state: "buffering",
      waitingForVideoSync: false,
      // Past maxVideoQueue for a hardware decoder (30): it is holding more
      // than enough to produce the frame this rebuffer is waiting for.
      video: { isSoftware: false, worker: false, queueSize: 61 },
      audioBuffered: 6.2,
      rendererQueue: 0,
      queuedVideo: packetRun((t) => videoPacket(t), 10, 16, 1 / 24),
      queuedAudio: packetRun((t) => audioPacket(t), 10, 16, 0.02),
    });
    await f.tick();
    expect(f.readPacket).not.toHaveBeenCalled();
    expect(f.videoDecode).not.toHaveBeenCalled();
  }, 20_000);
});

// ---------------------------------------------------------------------------
// P3 restart barrier — concurrent seek/track-switch/quality-switch.
//
// Team lead's framing: this is the same class of problem as M1 (reentrancy/
// races caught only by real-device black-box testing, because nothing in the
// suite exercised the concurrent shape). The supersede branch in
// notifySeekCompletion() (a newer seek/switch bumped seekSessionId while an
// older one was still armed) and the abandonSupersededSeek() /
// resumeAfterOrphanedSeek() backstop pair had ZERO coverage before this —
// every existing seek-sync test above arms and completes a SINGLE session.
// These lock the concurrency invariant: a superseded seek must release the
// barrier it armed, must NOT run the winning operation's resume/paused
// transition, and — if truly nobody else resolves "seeking" — the backstop
// must, exactly once, whichever of the two racing paths gets there first.
// ---------------------------------------------------------------------------
describe("MoviPlayer P3: restart barrier under concurrent seek/switch", () => {
  it("notifySeekCompletion releases the barrier for a superseded session without running the winner's resume", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    const seeked = vi.fn();
    player.trackManager.setTracks([videoTrack]);
    player.on("seeked", seeked);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");
    stateManager.setState("seeking");

    Object.assign(player as any, {
      // Session 1 armed the barrier; session 2 (a second seek, or a track/
      // quality switch that bumps seekSessionId to invalidate the first)
      // has since taken over.
      seekSessionId: 2,
      seekArmedSessionId: 1,
      seekTargetTime: 42, // the superseding op's own target — must survive untouched
      waitingForVideoSync: true,
      seekingToKeyframe: true,
      wasPlayingBeforeSeek: true,
      videoRenderer: { getQueueSize: () => 1 }, // a frame WOULD complete session 1 if not stale
    });

    // A late frame callback from session 1's decoder pipeline arrives after
    // session 2 has already taken over.
    (player as any).notifySeekCompletion(1.0);

    // The dead session's barrier is released — otherwise the pipeline sits
    // in "seeking"/"buffering" forever, since only a completion for the
    // (now impossible) old session would ever have cleared it.
    expect((player as any).waitingForVideoSync).toBe(false);
    expect((player as any).seekingToKeyframe).toBe(false);
    // But session 1 does NOT own the resume — it must not fire "seeked", and
    // must not touch the state the winner (session 2) is still using.
    expect(seeked).not.toHaveBeenCalled();
    expect((player as any).seekTargetTime).toBe(42);
    expect((player as any).wasPlayingBeforeSeek).toBe(true);
    expect(stateManager.getState()).toBe("seeking"); // untouched — session 2's to resolve
  }, 20_000);

  it("notifySeekCompletion for the CURRENT session still completes normally after an earlier session was superseded", async () => {
    // The barrier must not be permanently wedged by handling a supersede —
    // the very next real completion (for whichever session now owns it)
    // has to go through the normal path.
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    player.trackManager.setTracks([videoTrack]);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");
    stateManager.setState("seeking");

    Object.assign(player as any, {
      seekSessionId: 2,
      seekArmedSessionId: 1,
      seekTargetTime: 42,
      waitingForVideoSync: true,
      videoRenderer: { getQueueSize: () => 1 },
    });
    (player as any).notifySeekCompletion(1.0); // superseded — released, not completed
    expect((player as any).waitingForVideoSync).toBe(false);

    // Session 2 now arms its own completion.
    Object.assign(player as any, {
      seekArmedSessionId: 2,
      seekTargetTime: 55,
      waitingForVideoSync: true,
      wasPlayingBeforeSeek: false,
      wasPlayingBeforeRebuffer: false,
    });
    (player as any).notifySeekCompletion(55);

    expect((player as any).waitingForVideoSync).toBe(false);
    expect((player as any).seekTargetTime).toBe(-1); // real completion clears it
  }, 20_000);

  it("abandonSupersededSeek releases the barrier only if its own session still owns the arming", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});

    // Case 1: session 1's own arming is still in place when it discovers the
    // session moved on — must release, since nothing else will.
    Object.assign(player as any, {
      seekSessionId: 2,
      seekArmedSessionId: 1,
      waitingForVideoSync: true,
      seekingToKeyframe: true,
    });
    (player as any).abandonSupersededSeek(1);
    expect((player as any).waitingForVideoSync).toBe(false);
    expect((player as any).seekingToKeyframe).toBe(false);
  }, 20_000);

  it("abandonSupersededSeek does NOT stomp a barrier a later session has already re-armed", async () => {
    // Session 1 discovers it was superseded, but by the time it checks,
    // session 3 has already armed its OWN barrier (seekArmedSessionId=3).
    // Session 1 releasing unconditionally would tear down session 3's live
    // wait for a frame that hasn't arrived yet.
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});

    Object.assign(player as any, {
      seekSessionId: 3,
      seekArmedSessionId: 3, // someone else already re-armed
      waitingForVideoSync: true,
      seekingToKeyframe: true,
    });
    (player as any).abandonSupersededSeek(1); // session 1's stale callback

    expect((player as any).waitingForVideoSync).toBe(true);
    expect((player as any).seekingToKeyframe).toBe(true);
  }, 20_000);

  it("resumeAfterOrphanedSeek backstop resolves 'seeking' to paused when nobody else owns the live session", async () => {
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    const seeked = vi.fn();
    player.on("seeked", seeked);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");
    stateManager.setState("seeking");

    Object.assign(player as any, {
      seekSessionId: 2,
      _liveSeekSession: -1, // no seek() call is actively in flight for session 2
      wasPlayingBeforeSeek: false,
      wasPlayingBeforeRebuffer: false,
      waitingForVideoSync: true,
      seekingToKeyframe: true,
    });

    (player as any).resumeAfterOrphanedSeek("a non-seek operation");

    expect(stateManager.getState()).toBe("paused");
    expect((player as any).waitingForVideoSync).toBe(false);
    expect((player as any).seekingToKeyframe).toBe(false);
    expect(seeked).toHaveBeenCalledOnce();
  }, 20_000);

  it("resumeAfterOrphanedSeek backstop is a no-op when a live seek() call still owns the current session", async () => {
    // The race this guards: the backstop timer and a live seek() for the
    // SAME (new) session both reach their resolution around the same time.
    // Whichever session is genuinely in flight must win; the backstop must
    // not double-resolve behind its back.
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    const seeked = vi.fn();
    player.on("seeked", seeked);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing");
    stateManager.setState("seeking");

    Object.assign(player as any, {
      seekSessionId: 2,
      _liveSeekSession: 2, // seek() for session 2 IS still in flight
      waitingForVideoSync: true,
    });

    (player as any).resumeAfterOrphanedSeek("a non-seek operation");

    // Untouched — the live seek owns resolving this, not the backstop.
    expect(stateManager.getState()).toBe("seeking");
    expect((player as any).waitingForVideoSync).toBe(true);
    expect(seeked).not.toHaveBeenCalled();
  }, 20_000);

  it("resumeAfterOrphanedSeek backstop is a no-op once the state has already left 'seeking'", async () => {
    // The other half of the race: the winning operation (a rendition swap,
    // a subtitle prefetch) already resolved the state by the time the
    // backstop timer fires. Must not re-resolve an already-settled state.
    stubBrowserGlobals();
    const { MoviPlayer } = await import("../../src/core/MoviPlayer");
    const player = new MoviPlayer({});
    const seeked = vi.fn();
    player.on("seeked", seeked);

    const stateManager = (player as any).stateManager;
    stateManager.setState("loading");
    stateManager.setState("ready");
    stateManager.setState("playing"); // already resolved — not "seeking"

    Object.assign(player as any, {
      seekSessionId: 2,
      _liveSeekSession: -1,
      waitingForVideoSync: false,
    });

    (player as any).resumeAfterOrphanedSeek("a non-seek operation");

    expect(stateManager.getState()).toBe("playing");
    expect(seeked).not.toHaveBeenCalled();
  }, 20_000);
});
